PADDING = 1514
MAX_VALUE = 3028
ENUMERATION_SOFT_LIMIT = 4_000_000


def real_prefix(values):
    for index, value in enumerate(values):
        if value == PADDING:
            return values[:index]
    return values[:]


class RowIndex:
    """Distinct validation real prefixes per class with their multiplicities."""

    def __init__(self, rows, classes):
        self.classes = classes
        self.counts = [0] * classes
        self.by_class = [[] for _ in range(classes)]
        self.lookup = [{} for _ in range(classes)]
        self.positions = {}
        for row in rows:
            cls = row['class']
            self.counts[cls] += 1
            prefix = tuple(real_prefix(row['values']))
            slot = self.lookup[cls].get(prefix)
            if slot is None:
                entry = [prefix, 1]
                self.lookup[cls][prefix] = entry
                self.by_class[cls].append(entry)
                index = {}
                for position, value in enumerate(prefix):
                    index.setdefault(value, []).append(position)
                self.positions[prefix] = index
            else:
                slot[1] += 1

    def total(self, cls):
        return self.counts[cls]


def _verify(values, lo, hi, start, order):
    for coordinate in order:
        check = values[start + coordinate]
        if check < lo[coordinate] or check > hi[coordinate]:
            return False
    return True


def _match(values, length, lo, hi, key, order, index):
    """True when some real window of this row lies inside the interval box."""
    slots = len(values) - length + 1
    if slots <= 0:
        return False
    low = lo[key]
    high = hi[key]
    if high - low + 1 <= slots:
        # Few values can satisfy the tightest coordinate: index them directly.
        for value in range(low, high + 1):
            for position in index.get(value, ()):
                start = position - key
                if 0 <= start < slots and _verify(values, lo, hi, start, order):
                    return True
        return False
    for start in range(slots):
        value = values[start + key]
        if low <= value <= high and _verify(values, lo, hi, start, order):
            return True
    return False


DOMAIN = MAX_VALUE + 1


def _sweep_masks(members, unique, coordinate):
    """Bitmask of patterns covering each value of one coordinate."""
    add = [[] for _ in range(DOMAIN)]
    remove = [[] for _ in range(DOMAIN)]
    for bit, position in enumerate(members):
        _, lo, hi = unique[position]
        low = lo[coordinate]
        high = hi[coordinate]
        add[low].append(1 << bit)
        remove[high].append(1 << bit)
    masks = [0] * DOMAIN
    active = 0
    for value in range(DOMAIN):
        if add[value]:
            for bit in add[value]:
                active |= bit
        masks[value] = active
        if remove[value]:
            for bit in remove[value]:
                active &= ~bit
    return masks


